module FSharp.Substance.RightSententialForm

let lBounds =
    set
        [
            "{"
            "("
            "LLPAREN"
            "["
            "[|"
        ]

let precede_declExpr = set ["(";";";"LLPAREN";"[";"[|"]

/// 1. +-是一元操作符号 2. 记录literal还没有实现
let follow_semicolon =
  set ["!";"(";"+";"-";"DUMMY";"FUN";"IDENT";"LET";"LITERAL";"OPEN";"[";"[|"]

open FSharp.LexYacc

